local MONTH_CARD_TYPE = {
    COMMON = 1  ,  -- 普通月卡
    LIFELONG = 2 , -- 终身月卡
}

function MonthlyCardRenewalDialog:OnShow()
    local monthCardData = StoreUtils.GetStoreComp():GetNormalMonthCardData()
    if monthCardData then
        local vo = CfUtils.GetCfVo(AutoIds.IdSetting602, "MonthCardVo" , monthCardData.monthCardId)
        local rewards = self:GetMonthCardRewards(vo)
        CfUtils.RefreshCommonGoodsListLight(self.CommonGoodsListLight, rewards)

        local isCurrency = table.count(monthCardData.prices) > 0
        CfUtils.SetActive(self.OriginalIcon.gameObject,isCurrency)
        CfUtils.SetActive(self.NowIcon.gameObject,isCurrency)
        if isCurrency then
            local goodsId = checkNumber(table.takeFirst(table.keys(monthCardData.prices)))
            local currencyVo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
            local dojo = monthCardData.prices[tostring(goodsId)]
            local price = checkNumber(dojo.current)
            CfUtils.FillImage(self.NowIcon , currencyVo.photoPath)
            CfUtils.FillImage(self.OriginalIcon , currencyVo.photoPath)
            local dojo = monthCardData.initPrices[tostring(goodsId)]
            CfUtils.FillText(self.NowCost,price)
            CfUtils.FillText(self.TxtOriginalCost,checkNumber(dojo.current))
        else
            local windowsPriceId = CfUtils.GetWindowsPriceId(monthCardData)
            CfUtils.FillText(self.NowCost,CfUtils.GetCustomDisplayPrice(windowsPriceId,monthCardData.channelProductId,30))
            CfUtils.FillText(self.TxtOriginalCost,CfUtils.GetCustomDisplayPrice(monthCardData.initPrice,nil,30))
        end


        if checkNumber(monthCardData.renewLeftSeconds) > 0 then
            CfUtils.FillText(self.TxtTime,CfUtils.GetTimeHMS4(monthCardData.renewLeftSeconds))
        else
            CfUtils.FillText(self.TxtTime,CfUtils.GetTimeHMS4(0))
        end
    end

    local time = os.time()
    local t = timestamp_to_time(time)
    CfUtils.WriteLocalData("LastPopUpMonthCardTime", checkNumber(t.day))
end


function MonthlyCardRenewalDialog:GetMonthCardRewards(vo)
    local data = {}
    for i, v in pairs(vo.firstRewards) do
        data[v.goodsId] = v.goodsNum
    end

    for i, v in pairs(vo.rewards) do
        if not isNull(data[v.goodsId]) then
            data[v.goodsId] = data[v.goodsId] + v.goodsNum * 30
        else
            data[v.goodsId] = v.goodsNum * 30
        end
    end

    local rewards = {}
    for i, v in pairs(data) do
        table.insert(rewards,{goodsId = i,goodsNum = v})
    end

    return rewards
end

