function MonthlyCardRenewalDialog:OnBtnCostClick()
    local monthCard = StoreUtils.GetStoreComp():GetNormalMonthCardData()
    if isNull(monthCard) then
        return
    end
    if self.isBuy then
        GameUtils.Toast(localize("月卡生效中，無法購買"))
        UIModule.BackDialog()
        return
    end
    ---@type SDKService
    local SDKService = import('Game.Entry.SDKService')
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting602, "MonthCardVo" , monthCard.monthCardId)

    local isOverLimit = checkNumber(monthCard.leftDrawnNum) <= 0
    if table.count(monthCard.prices) > 0 then
        ---价格一样  说明是原价  就不用二次确认框
        local goodsId = checkNumber(table.takeFirst(table.keys(monthCard.prices)))
        local dojo = monthCard.prices[tostring(goodsId)]
        local price = checkNumber(dojo.current)
        local originalPriceDojo = monthCard.initPrices[tostring(goodsId)]
        local originalPrice = checkNumber(originalPriceDojo.current)
        if originalPrice == price then
            ServerDifferenceMgr:WrapPrimaryCurrencyBuy({
                currency = goodsId,
                current = price,
            },Bind(self,self.RequestBuyUseCurrency))
        else
            local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
            UIModule.OpenDialog({ id = Constants.UITypeIds.MonthCardSecondComfirm, parameters = { data = {
                mainText = isOverLimit and localize("月卡已经到期，续费吧！") or localize("月卡即将到期，续费吧！"),
                subText = localize("现在续费，立减_num__name_购买后立刻获得_desc_,30日总共可获得以下奖励",{_num_ = string.format("<color=#e71f55>%s</color>",originalPrice - price),_name_ = goodsVo.name,
                                                                                                          _desc_ = self:GetGoodsDes(monthCard.monthCardId)
                }),
                rewards = self:GetMonthCardRewards(vo),
                callBack = function()
                    local dojo = monthCard.prices[tostring(goodsId)]
                    local price = checkNumber(dojo.current)
                    ServerDifferenceMgr:WrapPrimaryCurrencyBuy({
                        currency = goodsId,
                        current = price,
                    },Bind(self,self.RequestBuyUseCurrency))
                end
            } }})
        end
    else
        if monthCard.price == monthCard.initPrice then
            SDKService:GetInstance():PayMoney({
                productId = monthCard.productId,
                channelProductId = monthCard.channelProductId,
                productDesc = localize("购买月卡"),
                payAmount = monthCard.price,
                data = monthCard
            })
        else
            local windowsPriceId = CfUtils.GetWindowsPriceId(monthCard)
            local freeNum = CfUtils.GetPrice(windowsPriceId,monthCard.channelProductId) - CfUtils.GetPrice(monthCard.initPrice,nil)

            local desc = isOverLimit and localize('月卡已经到期,现在续费，立减_symbol__num_',{_symbol_ = CfUtils.GetCurrerySymbol(),_num_ = string.format("<color=#e71f55>%s</color>", freeNum)})
                    or localize('月卡即将到期,现在续费，立减_symbol__num_',{_symbol_ = CfUtils.GetCurrerySymbol(), _num_ = string.format("<color=#e71f55>%s</color>", freeNum)})
            GameUtils.SecondConfirm(desc,function()
                        SDKService:GetInstance():PayMoney({
                            productId = monthCard.productId,
                            channelProductId = monthCard.channelProductId,
                            productDesc = localize("购买月卡"),
                            payAmount = monthCard.price,
                            data = monthCard
                        })
                    end,
                    nil,localize("购买后立刻获得_desc_",{_desc_ = self:GetGoodsDes(monthCard.monthCardId)}))
        end
    end
end

function MonthlyCardRenewalDialog:GetGoodsDes(monthCardId)
    local des = ""
    ---@type MonthCardVo
    local vo =  CfUtils.GetCfVo(AutoIds.IdSetting602, "MonthCardVo" , monthCardId)
    if not isNull(vo) then
        local rewards = vo.firstRewards
        for i, v in pairs(rewards) do
            local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(v.goodsId)
            if not isNull(goodsVo) then
                des = des..string.format("<color=#e71f55>%s</color>",v.goodsNum)..goodsVo.name
            end
            if i ~= #rewards then
                des = des.."+"
            end
        end
    end
    return des
end



function MonthlyCardRenewalDialog:RequestBuyUseCurrency(isSuccess)
    if not isSuccess then
        return
    end
    local monthCard = StoreUtils.GetStoreComp():GetNormalMonthCardData()
    ---买完以后 标记改一下
    monthCard.isRenew = 0
    --- 这个界面只能买普通月卡
    xRecord.af_internal('pay_monthly_card')
    local goodsId = checkNumber(table.takeFirst(table.keys(monthCard.prices)))
    local dojo = monthCard.prices[tostring(goodsId)]
    local price = checkNumber(dojo.current)
    GameUtils.Request(Interfaces.StoreMonthCardBuy, {productId = monthCard.productId,num = 1, currency = goodsId}, function(request, response)
        GoodsUtils.ConsumeGoods({{goodsId = goodsId,num = price, productId = monthCard.productId}})
        if response.data.rewards then
            GoodsUtils.DrawRewards(response.data.rewards,true)
            CfUtils.DialogOpen(Constants.UITypeIds.UICommonRewardPop, { rewards = response.data.rewards ,cb = function() self:OnBtnCloseClick()  end})
        end
    end)
end

function MonthlyCardRenewalDialog:OnEventSdkEvent(parameters)
    --- sdk pay succeed
    if parameters.event == Constants.EventNames.EVENT_SDK_PAY then
        local monthCard = StoreUtils.GetStoreComp():GetNormalMonthCardData() or {}
        self.isBuy = true
        ---买完以后 标记改一下
        monthCard.isRenew = 0
        -- self:OnBtnCloseClick()
    end
end

return MonthlyCardRenewalDialog